head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > P > firstSet]<br/>Key 에 값(Value)을 정의하지 않았을때 원본값(Origin Value)이 할당되지 않은 상태를 유지할지 설정합니다.",
    "validation" : [
        "원본값(Origin Value)은 Key 에 최초로 할당된 값(Value)을 의미하며 이때 Key 의 '변경여부' 상태값은 false 입니다.",
        "data 영역의 use 속성을 true 로 설정하여 디자인 시 정의한 값(Value)을 원본값(Origin Value)으로 할당할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }    

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // let properties = {
    //     firstSet: con_firstSet.getText()
    // }

    // let cList = $c.gcm.createCList(properties);

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strInput = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataMap ' + strNameSpace + ' id="target1" baseNode="map">';        
    strTarget += '<w2:keyInfo>';
    strTarget += '<w2:key dataType="text" id="key1" name="name1"></w2:key>';
    strTarget += '</w2:keyInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<key1><![CDATA[origin_value]]></key1>';    
    strTarget += '</w2:data>';
    strTarget += '</w2:dataMap>';      

    $p.data.create(strTarget);

	// input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');

    scwin.btn_getOriginal_onclick();
}



scwin.btn_getModifiedJSON_onclick = function (e) {
    let rtn = target1.getModifiedJSON();
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("getModifiedJSON : " + jsonString);  
}



scwin.btn_getOriginal_onclick = function (e) {    
    let rtn = "";

    rtn = target1.getOriginal("key1");
    wf_body_bottom.getObj("scwin").setReturnValue("getOriginal : " + rtn);  

    scwin.btn_getModifiedJSON_onclick();
};
